package io.github.miklires.mclans;import io.github.miklires.mclans.api.MClansApi;import io.github.miklires.mclans.clan.*;import io.github.miklires.mclans.command.*;import io.github.miklires.mclans.economy.EconomyBridge;import io.github.miklires.mclans.gui.ClanGui;import io.github.miklires.mclans.storage.ClanRepository;import io.github.miklires.mclans.util.PluginScheduler;import io.papermc.paper.plugin.lifecycle.event.types.LifecycleEvents;import org.bstats.bukkit.Metrics;import org.bukkit.plugin.*;import org.bukkit.plugin.java.JavaPlugin;
public final class MClansPlugin extends JavaPlugin{private PluginScheduler scheduler;private ClanRepository repository;private ClanService service;@Override public void onEnable(){saveDefaultConfig();getConfig().options().copyDefaults(true);if(!java.util.Set.of("en_US","ru_RU").contains(getConfig().getString("language","en_US")))getConfig().set("language","en_US");getConfig().set("config-version",2);saveConfig();scheduler=new PluginScheduler(this);try{repository=new ClanRepository(getDataFolder().toPath().resolve("data").resolve("mclans"));EconomyBridge economy=new EconomyBridge();boolean economyReady=economy.hook();service=new ClanService(this,repository,economy);ClanGui gui=new ClanGui(this,service);getServer().getPluginManager().registerEvents(gui,this);getServer().getPluginManager().registerEvents(new ClanListener(service),this);getLifecycleManager().registerEventHandler(LifecycleEvents.COMMANDS,e->{e.registrar().register("clan","Manage a clan",java.util.List.of("clans"),new ClanCommand(this,service,gui));e.registrar().register("cc","Clan chat",java.util.List.of("clanchat"),new ClanChatCommand(service));});getServer().getServicesManager().register(MClansApi.class,new ClansApiService(repository),this,ServicePriority.Normal);getServer().getOnlinePlayers().forEach(p->service.refresh(p.getUniqueId()));int id=Math.max(0,getConfig().getInt("metrics.bstats-id",0));if(getConfig().getBoolean("metrics.enabled",true)&&id>0)new Metrics(this,id);getLogger().info("mClans "+getPluginMeta().getVersion()+" is ready; economy="+(economyReady?"Vault":"disabled"));}catch(RuntimeException e){getLogger().severe("mClans failed to start: "+e.getMessage());getServer().getPluginManager().disablePlugin(this);}}@Override public void onDisable(){getServer().getServicesManager().unregisterAll(this);if(repository!=null)repository.close();}public PluginScheduler scheduler(){return scheduler;}public void reloadRuntime(){reloadConfig();getConfig().options().copyDefaults(true);service.reload();}}
